//! 🔀️ Declared enum variants retain one typed child carrier and the original discriminator source.
use quote::{quote,format_ident};
use syn::{DeriveInput,Data,Fields};
use super::super::{container_native_owned_path,ContainerAttrs,parse_variant_attrs,statement_keyword,variant_wire_name};
pub fn expand(input:&DeriveInput,attrs:&ContainerAttrs)->syn::Result<proc_macro2::TokenStream>{
 let Data::Enum(data)=&input.data else{return Err(syn::Error::new_spanned(&input.ident,"Receive derive supports enums only"))};let name=&input.ident;let vis=&input.vis;let value:syn::Path=syn::parse_str(attrs.crate_path.as_deref().unwrap_or("::semio_framework_value"))?;let value_path=attrs.crate_path.as_deref().unwrap_or("::semio_framework_value");let native=container_native_owned_path(attrs);let native_path=quote!(#native).to_string();let tree=quote!(#native::native_decoding::owned::tree);let mut definitions=Vec::new();let mut carriers=Vec::new();let mut wires=Vec::new();let mut statements=Vec::new();let mut constructors=Vec::new();let mut unit=Vec::new();let mut direct_types=Vec::new();let mut direct_constructors=Vec::new();
 for variant in &data.variants{
  let attr=parse_variant_attrs(&variant.attrs)?;let id=&variant.ident;let wire=variant_wire_name(&id.to_string(),&attr.rename,&attrs.rename_all);let statement=statement_keyword(&id.to_string(),&variant.attrs);let carrier=format_ident!("{}{}NativeVariant",name,id);let tag_type=format_ident!("{}{}NativeTag",name,id);let payload=format_ident!("{}{}NativePayload",name,id);let internal=attrs.tag.is_some()&&attrs.content.is_none();let external_unit=attrs.tag.is_none()&&matches!(variant.fields,Fields::Unit);let field_casing=attrs.field_rename_all(&attr);let casing=field_casing.as_ref().map(|value|quote!(rename_all=#value,));
  if attrs.tag.is_some(){definitions.push(quote!(#[derive(#value::RetireOwned,#value::NativeReceive)]#[value(crate=#value_path,native_owned=#native_path)]#vis enum #tag_type{#[value(rename=#wire)]Value}));}
  let fields=match &variant.fields{
   Fields::Named(named)=>{let members=named.named.iter().map(|field|field.ident.as_ref().unwrap()).collect::<Vec<_>>();let typed=named.named.iter().map(|field|{let member=field.ident.as_ref().unwrap();let ty=&field.ty;let attributes=field.attrs.iter().filter(|attribute|attribute.path().is_ident("value"));quote!(#(#attributes)*#member:#ty)}).collect::<Vec<_>>();if internal{constructors.push(quote!(#name::#id{#(#members:value.#members,)*}));quote!(#(#typed,)*)}else{definitions.push(quote!(#[derive(#value::RetireOwned,#value::NativeReceive)]#[value(crate=#value_path,native_owned=#native_path,#casing)]#vis struct #payload{#(#typed,)*}));constructors.push(quote!(#name::#id{#(#members:value.payload.#members,)*}));quote!(payload:#payload)}},
   Fields::Unnamed(unnamed)=>{if internal&&unnamed.unnamed.len()!=1{return Err(syn::Error::new_spanned(variant,"internally tagged native variants require one declared record payload"));}let types=unnamed.unnamed.iter().map(|field|&field.ty).collect::<Vec<_>>();if types.len()==1{let ty=types[0];constructors.push(quote!(#name::#id(value.payload)));if internal{if let Some(content)=&attr.content{quote!(#[value(rename=#content)]payload:#ty)}else{quote!(#[value(flatten)]payload:#ty)}}else{quote!(payload:#ty)}}else{let indices=(0..types.len()).map(syn::Index::from).collect::<Vec<_>>();definitions.push(quote!(#[derive(#value::RetireOwned,#value::NativeReceive)]#[value(crate=#value_path,native_owned=#native_path)]#vis struct #payload(#(#types),*);));constructors.push(quote!(#name::#id(#(value.payload.#indices),*)));quote!(payload:#payload)}},
   Fields::Unit=>{constructors.push(quote!(#name::#id));quote!()},
  };
  let direct_type=match &variant.fields{
   Fields::Named(named)=>{let members=named.named.iter().map(|field|field.ident.as_ref().unwrap()).collect::<Vec<_>>();if internal{let typed=named.named.iter().map(|field|{let member=field.ident.as_ref().unwrap();let ty=&field.ty;let attributes=field.attrs.iter().filter(|attribute|attribute.path().is_ident("value"));quote!(#(#attributes)*#member:#ty)});definitions.push(quote!(#[derive(#value::RetireOwned,#value::NativeReceive)]#[value(crate=#value_path,native_owned=#native_path,#casing)]#vis struct #payload{#(#typed,)*}));}direct_constructors.push(quote!(#name::#id{#(#members:value.#members,)*}));quote!(#payload)},
   Fields::Unnamed(unnamed)=>{let types=unnamed.unnamed.iter().map(|field|&field.ty).collect::<Vec<_>>();if types.len()==1{let ty=types[0];direct_constructors.push(quote!(#name::#id(value)));quote!(#ty)}else{let indices=(0..types.len()).map(syn::Index::from).collect::<Vec<_>>();direct_constructors.push(quote!(#name::#id(#(value.#indices),*)));quote!(#payload)}},
   Fields::Unit=>{definitions.push(quote!(#[derive(#value::RetireOwned,#value::NativeReceive)]#[value(crate=#value_path,native_owned=#native_path)]#vis struct #payload{}));direct_constructors.push(quote!(#name::#id));quote!(#payload)},
  };direct_types.push(direct_type);
  let body=if let Some(tag)=&attrs.tag{if let Some(content)=&attrs.content{if matches!(variant.fields,Fields::Unit){quote!(#[value(rename=#tag)]__semio_tag:#tag_type)}else{quote!(#[value(rename=#tag)]__semio_tag:#tag_type,#[value(rename=#content)]#fields)}}else{quote!(#[value(rename=#tag)]__semio_tag:#tag_type,#fields)}}else if external_unit{definitions.push(quote!(#[derive(#value::RetireOwned,#value::NativeReceive)]#[value(crate=#value_path,native_owned=#native_path)]#vis enum #carrier{#[value(rename=#wire)]Value}));quote!()}else{quote!(#[value(rename=#wire)]#fields)};
  if !external_unit{definitions.push(quote!(#[derive(#value::RetireOwned,#value::NativeReceive)]#[value(crate=#value_path,native_owned=#native_path,#casing)]#vis struct #carrier{#body}));}
  carriers.push(carrier);wires.push(wire);statements.push(statement);unit.push(external_unit);
 }
 let owner=quote!(#native::native_decoding::owned);let variant_count=carriers.len();let indices=(0..variant_count).collect::<Vec<_>>();let all_indices=(0..variant_count*2).collect::<Vec<_>>();let all_constructors=constructors.iter().chain(direct_constructors.iter()).collect::<Vec<_>>();let all_types=carriers.iter().map(|ty|quote!(#ty)).chain(direct_types.iter().cloned()).collect::<Vec<_>>();let selected=format_ident!("{}NativeSelectedVariant",name);let variants=all_indices.iter().map(|i|format_ident!("Variant{}",i)).collect::<Vec<_>>();
 let schema_all=indices.iter().zip(wires.iter()).map(|(index,wire)|{let ordinal=*index as u32;quote!(#index=>Some(#owner::NativeRecordSchema::Leaf(#owner::NativeSchemaLeaf{name:#wire,ordinal:#ordinal})))}).collect::<Vec<_>>();let schema_statements=indices.iter().zip(statements.iter()).map(|(index,statement)|{let ordinal=*index as u32;quote!(#index=>Some(#owner::NativeRecordSchema::Leaf(#owner::NativeSchemaLeaf{name:#statement,ordinal:#ordinal})))}).collect::<Vec<_>>();let schema_unit=indices.iter().zip(unit.iter()).map(|(index,unit)|quote!(#index=>if #unit{Self::__semio_native_variant_all(index)}else{Some(#owner::NativeRecordSchema::Skip)})).collect::<Vec<_>>();let schema_data=indices.iter().zip(unit.iter()).map(|(index,unit)|quote!(#index=>if #unit{Some(#owner::NativeRecordSchema::Skip)}else{Self::__semio_native_variant_all(index)})).collect::<Vec<_>>();let schema_alternatives=indices.iter().zip(carriers.iter()).zip(unit.iter()).map(|((index,carrier),unit)|if *unit{quote!(#index=>Some(#owner::NativeRecordSchema::Skip))}else{quote!(#index=>Some(#owner::NativeRecordSchema::Splice{fields:<#carrier as #owner::NativeRecordFields>::native_schema_fields(),count:<#carrier as #owner::NativeRecordFields>::native_schema_count()}))}).collect::<Vec<_>>();
 let tag_schema=if let Some(tag)=&attrs.tag{quote!((index==0).then_some(#owner::NativeRecordSchema::Leaf(#owner::NativeSchemaLeaf{name:#tag,ordinal:0})))}else{quote!(None)};let tag=if attrs.tag.is_some(){quote!(Some(unsafe{#owner::NativeSchemaFields::native(Self::__semio_native_variant_tag)}))}else{quote!(None)};let implementation_where=if attrs.receive_recursive{quote!{}}else{quote!(where #(#all_types:#native::native_decoding::NativeReceive<dyn #tree::NativeValueSource>,)*)};
 let enum_machine=quote!(#owner::enum_machine);
 let bounds=quote!(where #(#all_types:#native::native_decoding::NativeReceive<dyn #tree::NativeValueSource>,)*);
 let born=all_indices.iter().zip(variants.iter()).zip(all_constructors.iter()).map(|((index,variant),construct)|quote!(#index=>Some(Self::#variant(#enum_machine::EnumChild::born(|value|{let _=&value;#construct}))))).collect::<Vec<_>>();
 Ok(quote!{
 #(#definitions)*
 impl #name{fn __semio_native_variant_all(index:usize)->Option<#owner::NativeRecordSchema>{match index{#(#schema_all,)*_=>None}}fn __semio_native_variant_units(index:usize)->Option<#owner::NativeRecordSchema>{match index{#(#schema_unit,)*_=>None}}fn __semio_native_variant_data(index:usize)->Option<#owner::NativeRecordSchema>{match index{#(#schema_data,)*_=>None}}fn __semio_native_variant_tag(index:usize)->Option<#owner::NativeRecordSchema>{#tag_schema}fn __semio_native_variant_statements(index:usize)->Option<#owner::NativeRecordSchema>{match index{#(#schema_statements,)*_=>None}}fn __semio_native_variant_alternatives(index:usize)->Option<#owner::NativeRecordSchema>{match index{#(#schema_alternatives,)*_=>None}}fn __semio_native_variant_spec()->#tree::variant::NativeVariantSpec{#tree::variant::NativeVariantSpec{all:unsafe{#owner::NativeSchemaFields::native(Self::__semio_native_variant_all)},units:unsafe{#owner::NativeSchemaFields::native(Self::__semio_native_variant_units)},data:unsafe{#owner::NativeSchemaFields::native(Self::__semio_native_variant_data)},count:#variant_count,statements:unsafe{#owner::NativeSchemaFields::native(Self::__semio_native_variant_statements)},tag:#tag}}}
 unsafe impl #owner::NativeRecordFields for #name{fn native_schema_count()->usize{1}fn native_schema_field(index:usize)->Option<#owner::NativeRecordSchema>{(index==0).then_some(#owner::NativeRecordSchema::Union{fields:unsafe{#owner::NativeSchemaFields::native(Self::__semio_native_variant_alternatives)},count:#variant_count})}}
 #vis enum #selected #bounds{#(#variants(#enum_machine::EnumChild<#tree::NativeReceiveSlot<dyn #tree::NativeValueSource,#all_types,#owner::SharedFrame>,#all_types,#name>),)*}
 impl<I:#tree::NativeValueSource+?Sized>#enum_machine::NativeEnumChildren<I,#name> for #selected #bounds{
  fn spec()->#tree::variant::NativeVariantSpec{#name::__semio_native_variant_spec()}
  fn variants()->usize{#variant_count}
  fn born(index:usize)->Option<Self>{match index{#(#born,)*_=>None}}
  fn child(&self)->&dyn #enum_machine::EnumChildOps<I,#name>{match self{#(Self::#variants(child)=>child,)*}}
  fn child_mut(&mut self)->&mut dyn #enum_machine::EnumChildOps<I,#name>{match self{#(Self::#variants(child)=>child,)*}}
 }
 impl<I:#tree::NativeValueSource+?Sized>#native::native_decoding::NativeReceive<I>for #name #implementation_where{type Receiver=#enum_machine::NativeEnumReceiver<I,#name,#selected>;fn receiver()->Self::Receiver{#enum_machine::NativeEnumReceiver::birth()}
  fn receiver_template(subset:bool)->Option<#native::native_decoding::NativeSeedTemplate<Self::Receiver>>{<Self::Receiver>::template(subset)}}
 })
}
